from collections import defaultdict

def k_cut_photos(n, w, x_values):
    temp_heap = []
    lo, hi = 0, w
    cuts = 0

    for i, x in enumerate(x_values):
        if x <= lo:
            temp_heap.append((x - lo, 1, i))
            lo = x
        elif hi <= x:
            temp_heap.append((hi - x, -1, i))
            hi = x
        elif x == lo:
            heapq.heappush(temp_heap, (0, -1, i))
            del temp_heap[0]
            lo = x
            cuts -= 1
        elif x == hi:
            if temp_heap and temp_heap[0][0] >= (x - w) - (hi - x):
                cuts += temp_heap[0][1]
            heapq.heapreplace(temp_heap, (0, -1, i))

    while lo < hi:
        _, value, i = heapq.heappop(temp_heap)
        cuts += value
        lo += 1

    return cuts

