def binary_search(items: List[int], key: int) -> int:
    if not items or len(items) < 2:
        return -1
    mid = len(items) // 2
    if items[mid] == key:
        return mid
    if items[mid] < key:
        return index(items, original, key - 1)
    return index(items, original, key + 1)

