def merge_sort(array, start, end, k, mod):
    if end - start == 1:
        return array[start:end], 0
    mid = (start + end) // 2
    l1, inv_l1 = merge_sort(array, start, mid, k, mod)
    l2, inv_l2 = merge_sort(array, mid, end, k, mod)
    i, j, inv_sum = start, mid, 0
    while i < mid and j < end:
        if l1[i] <= l2[j]:
            array[i + j - start] = l1[i]
            i += 1
        else:
            array[i + j - start] = l2[j]
            j += 1
            inv_sum += (mid - i)
    while i < mid:
        array[i + j - start] = l1[i]
        i += 1
    while j < end:
        array[i + j - start] = l2[j]
        j += 1
    return l1 + l2, inv_sum

