import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def find_fair_set(vertices, visited, candidate):
    for vertex in vertices:
        if vertex not in visited:
            if all(gcd(a, vertex) > 1 for a in candidate + visited):
                visited.add(vertex)
                candidate.append(vertex)
                break

def find_k_fair_sets(vertices, k, visited, candidate):
    if len(candidate) == k:
        yield tuple(candidate)
        return
    for vertex in sorted(vertices, key=lambda x: gcd(candidate[-1], x), reverse=True):
        if vertex not in visited and all(gcd(candidate[-1], x) > 1 for x in visited):
            visited.add(vertex)
            candidate.append(vertex)
            for subset in find_k_fair_sets(vertices, k, visited, candidate):
                yield subset
            visited.remove(vertex)
            candidate.pop()

