MOD = 10**9 + 7

def beautiful_trees(n, m, a, b):
    @lru_cache(maxsize=None)
    def dp(i, last, last_d):
        if last_d + 1 > max(last + 1, m - last_d):
            return 1
        if i == n:
            return 0
        # Include vertex i
        if last + 1 <= max(last + 1, m - last_d):
            include = dp(i + 1, last + 1, max(last + 1, m - last_d)) % MOD
        else:
            include = 0

        # Exclude vertex i
        exclude = dp(i + 1, last, last_d) % MOD

        return (include + exclude) % MOD

    return dp(1, 0, 0) % MOD

