from collections import defaultdict
from functools import lru_cache

def geometric_mean(arr):
    n = len(arr)
    @lru_cache(maxsize=None)
    def gmc(i, di):
        if di == 0:
            return 1
        gmc1 = 1
        gmc2 = -1
        for j in range(i - 1, i - di - 1, -1):
            gmc1 *= arr[j]
            gmc2 *= arr[i]
        return (gmc1 ** (1.0 / (di + 1))) ** di

    return gmc(0, n-1)

def solve(size, geometry_mean):
    subarrays = 0
    current_gmc = 1

    start = 0
    for end in range(size + 1):
        current_gmc *= geometry_mean[start:end]
        if current_gmc == geometry_mean ** size:
            subarrays += 1
            current_gmc = 1  # Reset current_gmc to 1 to consider the next potential subarray
        start += 1

    subarrays_sum = {
        0: 0
    }
    subarray_count = 0

    for end in range(size + 1):
        subarray_count += subarrays_sum[end - 1] * (start - end) + subarrays_sum[0]
        subarrays_sum[end] = subarrays * (start - end) + subarray_count

    return subarray_count

