from math import sqrt
from functools import lru_cache

class Graph:
    def __init__(self, n, m, a, b):
        self.n = n
        self.m = m
        self.a = a-1
        self.b = b-1
        self.tree = [(i, i+a) for i in range(n)]
        for i in range(n):
            for j in range(i+1, n):
                if (i-j) % a == 0:
                    k = j-i
                    if (i-j) % b == 0:
                        k = k + b-n
                    if (i-j) % b == 0 or i != a == (n & 1):
                        self.tree.append((j, k))
                    else:
                        self.tree.append((k, j))

    def kruskal(self):
        n = self.n
        m = self.m
        a = self.a - 1
        b = self.b - 1
        res = 1
        cost = [0] * n
        seen = [False] * n
        self.forest = [i for i in range(m+1)]
        while sum(cost) < n-1:
            old_empty = 1
            for i in range(n):
                if cost[i] == 0 and seen[i] == False and old_empty:
                    if a != i and (i-a) % b == 0:
                        chick = (i-a) // b
                        if (i-a) % b == 0 and i != a and not seen[i+chick] and not seen[chick] and seen[i+chick]:
                            break
                    else:
                        chicken = self.forest[i]
                        if self.forest[(chicken-b) % m] == chicken:
                            continue
                        res *= self.forest[(self.forest[(chicken-b) % m] - a) % m]
                        res %= 1e9 + 7
                        continue
                    weight = self.tree[i][0]
                    if seen[i] and (i - weight) % b != 0:
                        if not seen[weight]:
                            self.forest[i] = weight
                        else:
                            self.forest[i] = self.forest[self.forest.index(i)]
                    elif not seen[i]:
                        self.forest[i] = weight
                    old_empty = False
                elif cost[i] != 0:
                    chick = self.forest[i]
                    if seen[chick]:
                        seen[i] = True
                        res *= self.tree[chick][cost[chick]-1]
                    cost[i] += 1
        
        return res

class Solution:
    def number_of_beautiful_trees(self, n, m, a, b):
        g = Graph(n, m, a, b)
        return g.kruskal() % (10**9 + 7)

sol = Solution()
print(sol.number_of_beautiful_trees(int(input()), int(input()), int(input()), int(input())))
