from collections import defaultdict

def calculate_cap_on_side(side_color, ports):
    count = 0
    changes = defaultdict(int)
    for i in ports:
        changes[i] = changes[i] + 1 if side_color == 1 else changes[i] - 1
        count += changes[i]
    for i in range(1, len(ports)):
        if changes[i-1] < changes[i]:
            i += 1
            count += 1
    return count

