    visited = set()
    result = 0
    for i in range(len(adj_matrix)):
        if i not in visited:
            stack = [i]
            while stack:
                node = stack.pop()
                visited.add(node)
                for next_node, _ in adj_matrix[node]:
                    if next_node not in visited:
                        stack.append(next_node)
            result += 1
