def maxProSum(segment_pairs):
    def sum_of_length(segment):
        return segment[-1] - segment[0]

    # Topological sort based on the smaller of endpoint distance
    segment_pairs = sorted(segment_pairs, key=lambda x: min(x[0], x[2]) - max(x[0], x[2]))
    segments_sum = defaultdict(int)
    l_set, r_set = defaultdict(int), defaultdict(int)

    for lower, mid_coords, upper in segment_pairs:
