            lowest_end = 0
            while l_set[lowest_end + 1] > 0:
                lowest_end += 1
            l_set[lowest_end + 1] += 1
            lowest_end = 0
            while r_set[lowest_end + 1] > 0:
                lowest_end += 1
            r_set[lowest_end + 1] += 1
            l_set[mid_coords + 1] -= 1
            r_set[upper + 1] -= 1
            segments_sum.update({lowest_end + 1: sum_of_length([lower, mid_coords, upper])})

