            for index in indices:
                closest_cell = min(line[-1], key=lambda x: abs(x[0] - index[0]))
                line.append([min(closest_cell, new_cell) for new_cell in [index[1:]]])

            for i, row_map in enumerate(line, 2):
                if i == len(line):
                    indexes = row_map + [None]
                else:
                    keys_to_look = [k for (k, v) in row_map.items() if v is not None]
                    indexes = sorted(keys_to_look, reverse=True)[:len(line) - i]
                for j, cell in enumerate(indexes):
                    line[i][j] = cell

            result[0] = min(row)
            ranks = {row: ranks + row_line for ranks, row_line in zip(result[0:q], line)}
            result = result[1:]

            for shape_id_in_queue in shapes:
