            if gcd(values[i - 1], values[j - 1]) > 1:
                adj_list[i].append(j)
                adj_list[j].append(i)

    parent = list(range(n + 1))

    def findset(x):
        return x if parent[x] == x else findset(parent[x])

    connected_count = [0] * (n + 1)
    for u in range(1, n + 1):
        for v in adj_list[u]:
            u2 = findset(u)
            v2 = findset(v)
            if u2 == v2:
                continue
            parent[v2] = parent[u2]
            connected_count[u2] += 1

    result = [-1]

    def cut_sets(id):
        if len([i for i in findset(id) + findset(id + 1)]) == 2 and len([i for i in findset(id + 1) - findset(id)]) == 1:
            for i in findset(id) + findset(id + 1):
                parent[i] = id
        else:
            result = [id, id + 1]
            parent[result[0]] = result[1]
            parent[result[1]] = result[0]

    def union(id1, id2):
        cut_sets(id2)
        if len([i for i in findset(id1) + findset(id2)]) == 1:
            return

        for id lost in findset(id1):
            parent[findset[id lost]()] = id2

    mindist = 200 * n
    for x in range(1, 2 * k):
        if mindist > connected_count[x]:
            mindist = connected_count[x]
        for neighbor in adj_list[x]:
            if connected_count[neighbor] < mindist:
                cut_sets(neighbor)

    def is_connected(nbr, start_vertex):
        cousins = [nbr]
        while cousins[-1] != start_vertex:
            cousins.append(parent[cousins[-1]])
        if cousins == [start_vertex]:
            return True
        return False

    for i in range(k):
        start_vertex = i + 1
        try:
            is_complete = is_connected(k + i, start_vertex)
        except:
            is_complete = False

        if is_complete:
            result[0] = start_vertex
            break
        else:
            for neighbor in adj_list[start_vertex]:
                if not is_connected(neighbor, start_vertex):
                    cut_sets(start_vertex)
                    start_vertex = 0
