            if get_character(bits, bits_i, char, new_i) == char:
                new_i = larger
            else:
                new_i = smaller
            piles.append(new_i)
        for tree_i in reversed(range(3 * (n // 2), 0, -1)):
            pile_length = len(piles)
            if not bits & tree_i:
                continue
            smaller = i & 1 << tree_i
            larger = i & (~1 << tree_i)
            if larger != i:
                i ^= (preemptive_bits & ~1 << tree_i)
            s = min(i, s, priority[pile_length])
            return s, pile_length, i
    return s, len(piles), i

