from math import inf
from typing import List

def min_cost_to_earn_bracket_sequences(pattern: str, replacements: List[List[int]]) -> str or int:
    pattern_length = len(pattern)
    min_cost = inf
    optimal_sequence = None

    for i in range(1 << pattern_length):
        cost = 0
        sequence = ['-'] * pattern_length
        contains_ended = False
        for j in range(pattern_length):
            if i & (1 << j) > 0:
                cost += replacements[j][sequence[j] == '0']
                if sequence[j] == '0':
                    sequence[j] = pattern[j]
                else:
                    contains_ended = True
                if contains_ended and pattern[j] == ')':
                    return -1  # No valid sequence if we get '()'
            elif pattern[j] == '?':
                cost += replacements[j][0]
                if replacements[j][1] < replacements[j][0]:
                    cost += replacements[j][1]
                else:
                    cost += replacements[j][0]
                sequence[j] = '?'
            else:
                cost += replacements[j][1]
                if replacements[j][0] < replacements[j][1]:
                    cost += replacements[j][0]
                else:
                    cost += replacements[j][1]
                sequence[j] = pattern[j]

        if i == 0: continue
        if min_cost > cost or (min_cost == cost and sequence == pattern):
            min_cost = cost
            optimal_sequence = ''.join(sequence)

    return min_cost, optimal_sequence


